/**
 * @summary Fetch CSV column headers from a public Google Drive URL
 */
export const getGetTicketDriveHeadersUrl = (
  params: GetTicketDriveHeadersParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/tickets/drive-headers?${stringifiedParams}`
    : `/api/tickets/drive-headers`;
};

